transfer.sketch:
value Money: amount, tags: {cur: EUR|USD|JPY, asOf: Date, unit: major|minor}
value Edge:  from, to, on: Date, lossless: false, rate(tags) → exact decimal   -- row for tags.asOf
rule total:  works: declared(home), sameFrame: true                            -- sameFrame = same asOf

build(total, rows, args):                     -- args.to = home currency, from profile
  for r in rows:
    if r.tags.asOf ≠ args.asOf:
      return refuse(E_FRAME, asOf: [args.asOf, r.tags.asOf],
                    fix: "restate at one date: r.at(d)", where: callSite())
    c = convertTo(r, args.to)                 -- Edge(r.cur, args.to, on: r.tags.asOf)
    if c is Refusal: return c                 -- missing pair → E_SPACE, no silent identity
    acc = acc ++ [c]
  n = node("total", acc, args)                -- summed in exact decimals, not floats
  return roundToMinor(n, args.to)             -- the only lossy step; explicit, at report
